 card('Goods receipt register',formalGRNs.length+' GRN entries',formalGRNs.length?formalGRNs.slice().reverse().map(g=>{const p=formalPOs.find(x=>x.id===g.poId),l=p?.lines[g.lineIndex]||{};const pending=Number(g.received)-Number(g.accepted||0)-Number(g.rejected||0);return '<div class="line"><div><b>'+h(g.number)+' · '+h(l.code||'Material')+'</b><small>'+h(p?.number||g.poId)+' · '+h(p?.vendor||'')+' · Received '+g.received+' '+h(l.unit||'')+'</small><small>Accepted '+Number(g.accepted||0)+' · Rejected '+Number(g.rejected||0)+' · Pending QC '+pending+'</small></div><span class="tag">'+(pending>0?'QC PENDING':'INSPECTED')+'</span></div>'}).join(''):'<div class="empty compact">No GRNs recorded.</div>');
