function postAcceptedStock(po,line,grn,qty,qcId){
 if(qty<=0)return;
 if(line.itemType==='Fabric'){
  if(!grn.roll)throw new Error('Fabric GRN needs a unique roll number before QC stock posting.');
  const existing=fabrics.find(x=>x.grnId===grn.id);
  if(existing){
   if(norm(existing.roll)!==norm(grn.roll))throw new Error('The roll number on this GRN was changed after its first QC posting.');
   const postings=Array.isArray(existing.qcPostings)?existing.qcPostings:[];
   if(postings.some(x=>x.qcId===qcId))return;
   existing.meters=Number(existing.meters||0)+qty;
   existing.qcPostings=[...postings,{qcId,qty,postedAt:new Date().toISOString()}];
   existing.lastAcceptedAt=new Date().toISOString();
  }else{
   if(fabrics.some(x=>norm(x.roll)===norm(grn.roll)))throw new Error('Fabric roll number '+grn.roll+' already exists. Change the GRN roll number before posting.');
   fabrics.push({id:'FAB-GRN-'+qcId,type:'Purchased',code:line.code,design:grn.design||'',roll:grn.roll,colour:line.colour||'',width:grn.width||'',gsm:grn.gsm||'',meters:qty,supplier:po.vendor,lot:grn.supplierLot||grn.supplierChallan||grn.number,grnId:grn.id,poId:po.id,qcPostings:[{qcId,qty,postedAt:new Date().toISOString()}],acceptedAt:new Date().toISOString()});
  }
  fs(FK.fabric,fabrics);
 }else if(line.itemType==='Accessory'){
  if(!accessories.some(x=>x.id===line.itemId))throw new Error('Linked accessory master was not found. No stock was posted.');
  if(trimlogs.some(x=>x.qcId===qcId||x.id==='TRM-GRN-'+qcId))return;
  trimlogs.push({id:'TRM-GRN-'+qcId,qcId,itemId:line.itemId,kind:'IN',qty,date:grn.date,orderId:'PURCHASE',reference:grn.number,category:'Purchase GRN',supplier:po.vendor,poId:po.id,grnId:grn.id,notes:'QC accepted stock'});
  fs(FK.trimlog,trimlogs);
 }else throw new Error('Unsupported material type. Stock not posted.');
}
function purchaseOrderApprovalValidation(p,s,accessories){if(!p||!s)return 'Purchase order supplier was not found.';if(!['Draft'].includes(String(p.status||'')))return 'Only a Draft purchase order can be approved.';const date=String(p.orderDate||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T00:00:00'))||new Date(date+'T00:00:00').toISOString().slice(0,10)!==date)return 'Purchase order date is invalid.';if(!Array.isArray(p.lines)||!p.lines.length)return 'Add at least one material line before approval.';for(let i=0;i<p.lines.length;i++){const l=p.lines[i];if(!l)return 'Material line '+(i+1)+' is missing.';const qty=Number(l.qty),rate=Number(l.rate),gst=Number(l.gstPct);if(!String(l.code||'').trim())return 'Material line '+(i+1)+' needs a material code.';if(!Number.isFinite(qty)||qty<=0)return 'Material line '+(i+1)+' needs a positive quantity.';if(!Number.isFinite(rate)||rate<0)return 'Material line '+(i+1)+' has an invalid rate.';if(!Number.isFinite(gst)||gst<0||gst>100)return 'Material line '+(i+1)+' has an invalid GST percentage.';if(l.itemType==='Accessory'){if(!Number.isInteger(qty))return 'Accessory line '+(i+1)+' quantity must be a whole number.';if(!(accessories||[]).some(a=>a.id===l.itemId))return 'Accessory line '+(i+1)+' is not linked to a registered accessory.';}else if(l.itemType==='Fabric'){if(!String(l.unit||'').trim())return 'Fabric line '+(i+1)+' needs a unit.';}else return 'Material line '+(i+1)+' has an unsupported material type.';}return '';}
function grnReceiptValidation(p,line,qty,date,roll,already,rolls){if(!p||!line)return 'Purchase order line was not found.';if(!['Approved','Part received'].includes(String(p.status||'')))return 'Only an approved purchase order can receive goods.';if(!date||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(date)||Number.isNaN(Date.parse(date+'T00:00:00'))||new Date(date+'T00:00:00').toISOString().slice(0,10)!==date)return 'Enter a valid goods-received date.';if(!Number.isFinite(qty)||qty<=0||!Number.isFinite(Number(line.qty))||Number(line.qty)<=0||qty>Number(line.qty)-already+0.0001)return 'Received quantity must be positive and cannot exceed the remaining PO quantity. Remaining: '+(Number(line.qty)-already);if(line.itemType==='Fabric'&&!String(roll||'').trim())return 'Enter a unique fabric roll number.';if(line.itemType==='Fabric'&&(rolls||[]).some(x=>norm(x.roll)===norm(roll)))return 'This roll number already exists. Enter a unique roll number.';if(line.itemType==='Accessory'&&!Number.isInteger(qty))return 'Accessory receipt quantity must be a whole number of pieces.';return '';}
