 html=html.replace('<div class="settingrow" data-go="purchaseplanning">','<div class="settingrow" data-go="purchasing"><span class="settingicon">▣</span><div><b>Purchase Orders & procurement</b><small>Convert vendor requests into approved POs</small></div><span class="settingend">›</span></div><div class="settingrow" data-go="grn"><span class="settingicon">↓</span><div><b>Goods Receipt (GRN)</b><small>Receive material against approved purchase orders</small></div><span class="settingend">›</span></div><div class="settingrow" data-go="qualityinspection"><span class="settingicon">✓</span><div><b>Incoming quality inspection</b><small>Accept or reject received quantities before stock entry</small></div><span class="settingend">›</span></div><div class="settingrow" data-go="supplierpayments"><span class="settingicon">₹</span><div><b>Supplier payments & ledger</b><small>Record part-payments and view outstanding</small></div><span class="settingend">›</span></div><div class="settingrow" data-go="purchaseplanning">');
