const prevBackupProcurement=window.backupKeys;
window.backupKeys=function(){return [...new Set([...prevBackupProcurement(),POK,GRNK,PAYK,'pa_supplier_advance_allocations_v1','pa_style_cost_history_v1'])];};
const prevRestoreProcurement=window.restoreBusinessBackup;
window.restoreBusinessBackup=function(file){
 if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const b=JSON.parse(String(reader.result||''));if(!b||b.format!=='prasad-business-analyst-backup'||b.version!==1||!b.data||typeof b.data!=='object')throw new Error('Unsupported backup file.');const allowed=['pa_customer_purchase_orders_v1','pa_customer_master_v1','pa_garment_stock_ledger_v1','pa_manufacturing_v1','pa_drafts','pa_orders','pa_tax_invoices','pa_invoice_profile','pa_barcode_catalog_v1',K.moves,K.holds,K.labels,FK.fabric,FK.cut,FK.trim,FK.trimlog,BK,SUPK,PK,POK,GRNK,PAYK,'pa_supplier_advance_allocations_v1','pa_style_cost_history_v1'],entries=Object.entries(b.data);if(!entries.length||entries.some(([k,v])=>(!allowed.includes(k)&&!/^pa_invoice_seq_\\d{2}-\\d{2}$/.test(k))||typeof v!=='string'))throw new Error('Backup data is invalid.');for(const k of allowed){if(b.data[k]!==undefined){const parsed=JSON.parse(b.data[k]);if(!Array.isArray(parsed)&&!(k==='pa_manufacturing_v1'&&parsed&&typeof parsed==='object'))throw new Error('Invalid '+k+' data.');}}if(!confirm('Restore this backup? Current records will be replaced.'))return;window.backupKeys().forEach(k=>localStorage.removeItem(k));entries.forEach(([k,v])=>localStorage.setItem(k,v));alert('Backup restored. Reloading.');location.reload();}catch(e){alert('Restore failed: '+e.message)}};reader.readAsText(file);
};


/* STYLE COST REGISTER: effective-dated cost history; not a stock valuation engine */
const STYLE_COST_KEY='pa_style_cost_history_v1';
let styleCostRows=read(STYLE_COST_KEY,[]);
function styleCostPage(){
 const rows=styleCostRows.slice().sort((a,b)=>b.effectiveDate.localeCompare(a.effectiveDate)||b.createdAt.localeCompare(a.createdAt));
 return '<div class="heading"><div><small>PRODUCT COST CONTROL</small><h2>Style cost history</h2></div><span class="tag">'+rows.length+' COST RECORDS</span></div>'+
 card('Add verified style cost','Enter the cost per garment from a supplier bill, production calculation or approved manual estimate. Older entries remain in history; a new effective date creates a new cost version.','<form id="style-cost-form"><div class="two">'+field('style','Style / item code','e.g. PA-101')+field('description','Garment description','Boys kurta set')+'</div><div class="two">'+field('colour','Colour (optional)','Peach','text',false)+field('size','Size (optional)','24','text',false)+'</div><div class="two">'+field('unitCost','Cost per piece ₹','0','number')+field('effectiveDate','Effective from',today(),'date')+'</div><div class="two"><label>Cost source<select name="source"><option>Supplier purchase bill</option><option>Production cost calculation</option><option>Approved manual estimate</option><option>Other verified source</option></select></label>'+field('reference','Bill / calculation reference','Invoice or document no.','text',false)+'</div><label>Notes<textarea name="notes" rows="2" placeholder="What is included: fabric, stitching, trims, packing, freight etc."></textarea></label><button class="primary">Save cost version</button><p class="hint">Enter cost excluding recoverable GST. This register does not automatically calculate actual inventory valuation or profit. Estimates remain clearly identified as estimates.</p></form>')+
 card('Saved cost history','Newest effective date first · historical entries are retained',rows.length?rows.map(x=>'<div class="line"><div><b>'+h(x.style)+' · '+h(x.description||'')+' '+(x.colour?'· '+h(x.colour):'')+' '+(x.size?'· Size '+h(x.size):'')+'</b><small>Effective '+h(x.effectiveDate)+' · '+h(x.source)+' · '+h(x.reference||'No reference')+'</small><small>'+h(x.notes||'')+'</small></div><strong>'+money(x.unitCost)+'/pc</strong></div>').join(''):'<div class="empty compact">No style costs entered. Add verified cost records to build a reliable history.</div>')+
 card('Costing safeguards','Use these records as approved cost inputs, not as a claim of actual stock valuation.','<p class="hint">A cost version is selected by style, optional colour/size and effective date. Existing entries are never silently overwritten. Full customer/style/month gross-profit reporting still requires reconciled invoice lines, returns/credits, receipt allocations and a documented costing method.</p>');
}
function bindStyleCost(){
 const f=document.getElementById('style-cost-form');if(!f)return;
 f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.style=String(d.style||'').trim();d.description=String(d.description||'').trim();d.colour=String(d.colour||'').trim();d.size=String(d.size||'').trim();d.reference=String(d.reference||'').trim();d.notes=String(d.notes||'').trim();d.unitCost=Number(d.unitCost);if(!d.style||!d.effectiveDate||!Number.isFinite(d.unitCost)||d.unitCost<=0){alert('Enter a style, effective date and a positive cost per piece.');return;}const duplicate=styleCostRows.some(x=>x.style.toLowerCase()===d.style.toLowerCase()&&String(x.colour||'').toLowerCase()===d.colour.toLowerCase()&&String(x.size||'').toLowerCase()===d.size.toLowerCase()&&x.effectiveDate===d.effectiveDate);if(duplicate){alert('A cost version already exists for this style, colour, size and effective date. Use a new effective date to preserve history.');return;}d.id='SC-'+Date.now()+'-'+Math.floor(Math.random()*10000);d.createdAt=new Date().toISOString();d.status=d.source==='Approved manual estimate'?'Estimate':'Source recorded';styleCostRows.push(d);fs(STYLE_COST_KEY,styleCostRows);render();};
}
const oldRender=window.render;
window.render=function(){if(page==='stylecosts'){root.innerHTML=styleCostPage();bindStyleCost();return;}if(page==='inwardoutward'){root.innerHTML=movementPage();bind();return;}if(page==='workboard'){root.innerHTML=workboard();bind();return;}if(page==='labels'){root.innerHTML=labelPage();bind();return;}if(page==='fabric'){root.innerHTML=fabricScreen();bindMaterials();return;}if(page==='cutting'){root.innerHTML=cutScreen();bindMaterials();return;}if(page==='accessories'){root.innerHTML=trimScreen();bindMaterials();return;}if(page==='bom'){root.innerHTML=bomScreen();bindBom();return;}if(page==='purchaseplanning'){root.innerHTML=purchasePlanningScreen();bindPurchasePlanning();return;}if(page==='suppliers'){root.innerHTML=supplierPage();bindSuppliers();return;}oldRender();};
