const oldRestore=window.restoreBusinessBackup;
window.restoreBusinessBackup=function(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const b=JSON.parse(String(reader.result||''));if(!b||b.format!=='prasad-business-analyst-backup'||b.version!==1||!b.data||typeof b.data!=='object')throw new Error('Unsupported backup file.');const allowed=['pa_garment_stock_ledger_v1','pa_manufacturing_v1','pa_drafts','pa_orders','pa_tax_invoices','pa_invoice_profile','pa_barcode_catalog_v1',K.moves,K.holds,K.labels,FK.fabric,FK.cut,FK.trim,FK.trimlog,BK,SUPK,PK],entries=Object.entries(b.data);if(!entries.length||entries.some(([k,v])=>(!allowed.includes(k)&&!/^pa_invoice_seq_\\d{2}-\\d{2}$/.test(k))||typeof v!=='string'))throw new Error('Backup data is invalid.');for(const k of allowed){if(b.data[k]!==undefined){const parsed=JSON.parse(b.data[k]);if(k===K.moves||k===K.holds||k===FK.fabric||k===FK.cut||k===FK.trim||k===FK.trimlog||k===SUPK||k===PK||k==='pa_manufacturing_v1'||k==='pa_drafts'||k==='pa_orders'||k==='pa_tax_invoices'){if(!Array.isArray(parsed)&&!(k==='pa_manufacturing_v1'&&parsed&&typeof parsed==='object'))throw new Error('Invalid '+k+' data.');}}}if(!confirm('Restore this backup? Current records will be replaced.'))return;window.backupKeys().forEach(k=>localStorage.removeItem(k));entries.forEach(([k,v])=>localStorage.setItem(k,v));alert('Backup restored. Reloading.');location.reload();}catch(e){alert('Restore failed: '+e.message)}};reader.readAsText(file);};
window.addEventListener('load',()=>{document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.page==='more')setTimeout(()=>document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>navigate(x.dataset.go)),0);}));});
window.render();
